      esac
      fa_rest="$fa_body"
      while [ -n "$fa_rest" ]; do
        fa_c="${fa_rest%"${fa_rest#?}"}"
        case "$fa_c" in
          [cval]) exec "$FA_REAL_PKILL" "$@" ;;
        esac
        fa_rest="${fa_rest#?}"
      done
      ;;
  esac
