    # glued forms (-urot) ride the generic case below.
    -u|-U|-g|-s|-t|-P|-G|-r|-O|-q|-F)
      if [ "$#" -ge 2 ]; then
        sel="$sel $1 $2"
        shift 2
      else
        exec "$FA_REAL_PKILL" "$@"
      fi
      ;;
    -*) sel="$sel $1"; shift ;;
    *) break ;;
  esac
done
